edits.newText:
// Register the scroll-to-track + visibility implementations onto the
// passed handle; clear them on dispose / handle swap so a stale browser
// never answers a call.
useEffect(() {
  browserController?._scrollToTrack = scrollToTrack;

  browserController?._isTrackVisible = (String path) {
    final ctx = rowKeys[path]?.currentContext;
    final scrollableCtx = scroll.position.context.storageContext;
    final viewportBox =
        scrollableCtx.findRenderObject() as RenderBox?;
    final rowBox = ctx?.findRenderObject() as RenderBox?;
    if (viewportBox == null || rowBox == null) return false;

    final rowRect =
        Rect.fromLTWH(0, 0, rowBox.size.width, rowBox.size.height)
            .expandToInclude(
              rowBox.localToGlobal(Offset.zero, ancestor: viewportBox)
                  .translate(0, 0),
            );

    // Compute row bounds in viewport coordinates.
    final topLeft = rowBox.localToGlobal(Offset.zero,
        ancestor: viewportBox);
    final rowViewportRect = topLeft & rowBox.size;
    final viewportRect = Offset.zero & viewportBox.size;

    // Allow a small tolerance so “almost visible” doesn't flap.
    const tolerance = 8.0;
    final expandedViewport = viewportRect.inflate(tolerance);
    return expandedViewport.overlaps(rowViewportRect);
  };

  return () => browserController?._scrollToTrack = null;
}, [browserController]);

